// Owned and filled by task KBE-B. Until then it registers nothing; its registration line already exists, so the
// owning task edits only this file (and its own tests, pending list and contract exercises).
import type { FastifyInstance } from "fastify";
import type { ModuleDeps } from "../platform/index.ts";

/** Registers this file's routes and returns them as "METHOD /path" (none until KBE-B fills it). */
export function registerKpiFormulaRoutes(_app: FastifyInstance, _deps: ModuleDeps): string[] {
  return [];
}
// P4 route-file stub (T-DG4-BE-A; p4-plan §5.1, p4-work-split §I+C.1): target trajectories (slice A).
// Owned and filled by task KBE-B. Until then it registers nothing; its registration line already exists, so the
// owning task edits only this file (and its own tests, pending list and contract exercises).
import type { FastifyInstance } from "fastify";
import type { ModuleDeps } from "../platform/index.ts";

/** Registers this file's routes and returns them as "METHOD /path" (none until KBE-B fills it). */
export function registerTrajectoryRoutes(_app: FastifyInstance, _deps: ModuleDeps): string[] {
  return [];
}
// P4 route-file stub (T-DG4-BE-A; p4-plan §5.1, p4-work-split §I+C.1): KPI data-quality rules (slice A).
// Owned and filled by task KBE-B. Until then it registers nothing; its registration line already exists, so the
// owning task edits only this file (and its own tests, pending list and contract exercises).
import type { FastifyInstance } from "fastify";
import type { ModuleDeps } from "../platform/index.ts";

/** Registers this file's routes and returns them as "METHOD /path" (none until KBE-B fills it). */
export function registerDataQualityRoutes(_app: FastifyInstance, _deps: ModuleDeps): string[] {
  return [];
}
// kpi module route registration (P2): kpi-definitions (+ activate), baselines (+ validation), outcome-kpis
// (+ trajectory-approval) and value-pools (+ validation) - the 24 kpi operations of docs/api/openapi.yaml. Every route declares its access in
// `config.access` (the platform refuses to start otherwise) and its handler calls the policy function.
import type { Permission } from "@mth/shared";
import type { FastifyInstance, FastifyReply, FastifyRequest } from "fastify";
import type { ModuleDeps } from "../platform/index.ts";
import { registerBaselineRoutes } from "./baselines.ts";
import { registerBusinessCaseLineRoutes } from "./business-case-lines.ts";
import { registerBenefitFormulaRoutes } from "./benefit-formulas.ts";
import { registerBusinessCaseRoutes } from "./business-cases.ts";
import { registerCalculationRoutes } from "./calculations.ts";
import { registerFormulaVersionRoutes } from "./formula-versions.ts";
import { registerKpiDefinitionRoutes } from "./kpi-definitions.ts";
import { registerOutcomeKpiRoutes } from "./outcome-kpis.ts";
import { registerValuePoolRoutes } from "./value-pools.ts";
// P4 route files (T-DG4-BE-A stubs; p4-plan §5.1): KBE-B's, then KBE-C's.
import { registerAcceptPipelineRoutes } from "./accept-pipeline.ts";
import { registerKpiActualRoutes } from "./actuals.ts";
import { registerCalculationRunRoutes } from "./calculation-runs.ts";
import { registerDataQualityRoutes } from "./data-quality.ts";
import { registerKpiFormulaRoutes } from "./kpi-formulas.ts";
import { registerKpiStatusRoutes } from "./kpi-status.ts";
import { registerKpiVersionRoutes } from "./kpi-versions.ts";
import { registerRagOverrideRoutes } from "./rag-overrides.ts";
import { registerReportingPeriodRoutes } from "./reporting-periods.ts";
import { registerTrajectoryRoutes } from "./trajectories.ts";

export type RouteAdder = (
  app: FastifyInstance,
  method: "GET" | "POST" | "PATCH",
  url: string,
  permission: Permission,
  handler: (request: FastifyRequest, reply: FastifyReply) => Promise<unknown>,
) => void;

/** Registers every kpi route and returns them as "METHOD /path" (Fastify path syntax). */
export function registerKpiRoutes(app: FastifyInstance, deps: ModuleDeps): readonly string[] {
  const routes: string[] = [];
  const add: RouteAdder = (instance, method, url, permission, handler) => {
    instance.route({ method, url, config: { access: { permission } }, handler });
    routes.push(`${method} ${url}`);
  };
  registerKpiDefinitionRoutes(app, deps, add);
  registerBaselineRoutes(app, deps, add);
  registerOutcomeKpiRoutes(app, deps, add);
  registerValuePoolRoutes(app, deps, add);
  // P3 business cases and lines (T-DG3-KBE-B; ADR-0024 §1-§5): 11 operations, each with its own config.consumes.
  routes.push(...registerBusinessCaseRoutes(app, deps), ...registerBusinessCaseLineRoutes(app, deps));
  // P3 T09 benefit formulas, versions, calculations and Finance validation (T-DG3-KBE-C; ADR-0024 §5-§6): 13 operations.
  // The check route (POST /benefit-formulas/validate) is registered before the item routes it could shadow.
  routes.push(
    ...registerCalculationRoutes(app, deps),
    ...registerBenefitFormulaRoutes(app, deps),
    ...registerFormulaVersionRoutes(app, deps),
  );
  // P4 KBE-B: KPI versions, trajectories, data quality, KPI formulas.
  routes.push(
    ...registerKpiVersionRoutes(app, deps),
    ...registerTrajectoryRoutes(app, deps),
    ...registerDataQualityRoutes(app, deps),
    ...registerKpiFormulaRoutes(app, deps),
  );
  // P4 KBE-C: actuals, reporting periods, the accept pipeline, calculation runs, RAG overrides, KPI status.
  routes.push(
    ...registerKpiActualRoutes(app, deps),
    ...registerReportingPeriodRoutes(app, deps),
    ...registerAcceptPipelineRoutes(app, deps),
    ...registerCalculationRunRoutes(app, deps),
    ...registerRagOverrideRoutes(app, deps),
    ...registerKpiStatusRoutes(app, deps),
  );
  return routes;
}
// kpi (ADR-0002; master prompt §16 "formulas/KPI"): KPI definitions, baselines, T02 outcome KPIs and value pools (P2),
// with decimal arithmetic for every amount and KPI value (@mth/shared value.ts; never a float). Later stages add
// versioned formulas, KPI actuals and the benefit register (P4) through this same boundary.
//
// Missing data is Unknown (NULL), never zero; an outdated validation is stale, never "validated"; an unquantified
// value pool is never 0. Finance validation and trajectory approval are human actions by FIN and SP/BO - this module
// records them; it never grants a business approval by itself.
//
// Public interface:
//  - registerKpiModule: wiring hook called by the composition root (server.ts);
//  - loadKpiGateFacts / KpiGateFacts: facts for the product-gate G1/G2 criteria (workflows module, p2-work-split §3).
import type { FastifyInstance } from "fastify";
import type { ModuleDeps, ModuleRegistration } from "../platform/index.ts";
import { registerKpiRoutes } from "./routes.ts";

export { loadKpiGateFacts, type KpiGateFacts } from "./gate-facts.ts";
// P3 business cases (T-DG3-KBE-B): section completeness, baseline validation state (incl. Stale) and totals, for
// KBE-C's G4 fact loader.
export {
  baselineSha256,
  baselineValidationState,
  includedCaseIds,
  loadCaseTotals,
  missingSections,
  presentCases,
} from "./business-cases.ts";
export { activeLinesOf, toBusinessCaseLine } from "./business-case-lines.ts";
export { computeTotals, type TotalsInput, type TotalsLine } from "./totals.ts";
// P3 T09 benefit formulas (T-DG3-KBE-C): the kpi half of the G4 GateFactsProvider (business cases, section
// completeness, baseline validation incl. Stale, formula version validation per financial benefit line). server.ts
// wires it (BE-E).
export {
  buildKpiP3GateFacts,
  loadKpiP3GateFacts,
  type FormulaValidationFact,
  type KpiBenefitLineFact,
  type KpiCaseFact,
  type KpiP3GateFactsData,
} from "./p3-gate-facts.ts";

/** Freshness of a KPI or benefit value. Missing data is "unknown" and outdated data "stale", never zero or green. */
export const VALUE_FRESHNESS = ["unknown", "stale", "current"] as const;
export type ValueFreshness = (typeof VALUE_FRESHNESS)[number];

/** Wiring hook called by the composition root (server.ts). P2: registers the 24 kpi operations. */
export function registerKpiModule(app: FastifyInstance, deps: ModuleDeps): ModuleRegistration {
  const routes = registerKpiRoutes(app, deps);
  return Object.freeze({ module: "kpi", status: "active", deliversIn: "P2", routes: Object.freeze([...routes]) });
}

