import fs from "node:fs";
const doc = yaml.load(fs.readFileSync("docs/api/openapi.yaml","utf8"));
const ids = new Set(process.argv.slice(2));
for (const [p, item] of Object.entries(doc.paths)) for (const [m, op] of Object.entries(item)) {
  if (!op || !ids.has(op.operationId)) continue;
  console.log("=====", m.toUpperCase(), p, op.operationId);
  console.log(yaml.dump({params:[...(item.parameters||[]),...(op.parameters||[])], requestBody: op.requestBody, responses: op.responses, desc: op.description, xp: op["x-permission"]}, {lineWidth: 200}));
}
EOF
