// Shared route plumbing of the kpi module. Every mutation follows ONE order, inside ONE transaction:
//   1. read gate on the transformation (no transformation.read -> 404, existence not disclosed);
//   2. action gate (the route's write permission; denied -> 403, audited as authorization.denied - AUD lands here);
//   3. the transformation is not archived (422);
//   4. If-Match present and well-formed (428 / 400)          [changes of an existing record]
//   5. body validation with the @mth/shared zod mirrors (400), then business rules (422);
//   6. row lock, version equal to If-Match (409), record not archived (422);
//   7. the write with version + 1 (the p2_row_guard trigger refuses any other step) and exactly one audit event
//      (the deferred p2_audit_required trigger refuses a commit without it).
import { sql, type Db, type DbOrTx, type TransformationRow, type Tx } from "@mth/db";
import { PROBLEM_TYPES, type Permission } from "@mth/shared";
import { kpiListQuery } from "@mth/shared/schemas";
import type { FastifyReply, FastifyRequest } from "fastify";
import { z } from "zod";
import { principalOf, requireAction, requireRead, type ResolvedTarget } from "../access/index.ts";
import {
  cursorSchema,
  decodeCursor,
  filterHash,
  HttpProblem,
  idempotencyKeySchema,
  limitSchema,
  paginate,
  parse,
  parseQuery,
  problems,
  requestHash,
  sendVersioned,
  withIdempotency,
} from "../platform/index.ts";
import { findTransformation } from "../transformations/index.ts";
import { activeOrgUsersExist } from "./repository.ts";
import type { RuleViolation } from "./rules.ts";

export type KpiTable = "kpi_definition" | "baseline" | "outcome_kpi" | "value_pool";

export interface Scope {
  readonly target: ResolvedTarget;
  readonly transformation: TransformationRow;
}

export const transformationParams = z.strictObject({ transformationId: z.uuid() });
/**
 * Path params of a record route, e.g. { transformationId, baselineId } -> { transformationId, id }. A malformed id is a
 * 400 at `/params/<name>` (e.g. `/params/baselineId`), the pointer style of `parse` (T-DG2-ARCH-02).
 */
export function parseRecordParams(params: unknown, name: string): { transformationId: string; id: string } {
  const entries = new Map(Object.entries((params ?? {}) as Record<string, unknown>));
  const names = ["transformationId", name];
  const parsed = parse(
    z.strictObject(Object.fromEntries(names.map((n) => [n, z.uuid()]))),
    Object.fromEntries(names.map((n) => [n, entries.get(n)])),
    "params",
  );
  const ids = new Map(Object.entries(parsed));
  return { transformationId: ids.get("transformationId")!, id: ids.get(name)! };
}

/** Read gate (404) and the transformation row. */
export async function readScope(db: DbOrTx, request: FastifyRequest, transformationId: string): Promise<Scope> {
  const principal = principalOf(request);
  const target = await requireRead(db, principal, "transformation.read", {
    type: "transformation",
    id: transformationId,
  });
  const transformation = await findTransformation(db, transformationId);
  if (!transformation) throw problems.notFound();
  return { target, transformation };
}

/** Read gate (404), action gate (403), and a transformation that is not archived (422). */
export async function writeScope(
  db: DbOrTx,
  request: FastifyRequest,
  transformationId: string,
  permission: Permission,
): Promise<Scope> {
  const scope = await readScope(db, request, transformationId);
  await requireAction(db, principalOf(request), permission, scope.target);
  if (scope.transformation.archived_at !== null)
    throw problems.businessRule(
      "kpi.transformation_archived",
      "The transformation is archived; its KPI, baseline and value-pool records are read-only.",
    );
  return scope;
}

/** A violated business rule as a 422 problem with the field pointer. */
export function ruleProblem(v: RuleViolation): HttpProblem {
  return new HttpProblem({
    status: 422,
    type: PROBLEM_TYPES.validation,
    code: v.code,
    title: "Business rule violated",
    detail: v.detail,
    errors: [{ pointer: v.pointer, code: v.code, message: v.detail }],
  });
}

export function check(v: RuleViolation | null): void {
  if (v) throw ruleProblem(v);
}

/** Referenced record missing in this transformation (or archived): 422 with the field pointer. */
export function referenceProblem(pointer: string, detail: string): HttpProblem {
  return ruleProblem({ code: "validation.reference", detail, pointer });
}

/**
 * Separation of duties (ADR-0020 §3): Finance validation and trajectory approval are never done by the record's
 * creator. 403 with a specific code; audited like any other authorization denial.
 */
export function creatorDenied(
  code: string,
  detail: string,
  permission: Permission,
  record: { recordType: KpiTable; recordId: string; organizationId: string; transformationId: string },
): HttpProblem {
  return new HttpProblem({ status: 403, type: PROBLEM_TYPES.forbidden, code, title: "Forbidden", detail }).withDenial({
    permission,
    recordType: record.recordType,
    recordId: record.recordId,
    organizationId: record.organizationId,
    transformationId: record.transformationId,
  });
}

/** Named people (owner, steward) must be active users of the transformation's organization; 422 per field. */
export async function requireActiveUsers(
  db: DbOrTx,
  organizationId: string,
  named: readonly (readonly [field: string, userId: string | null | undefined])[],
): Promise<void> {
  for (const [field, userId] of named) {
    if (typeof userId === "string" && !(await activeOrgUsersExist(db, organizationId, [userId])))
      throw ruleProblem({
        code: "kpi.user_invalid",
        detail: "A named owner or steward must be an active user of the transformation's organization.",
        pointer: `/${field}`,
      });
  }
}

export function archivedRecord(kind: string): HttpProblem {
  return problems.businessRule(`${kind}.archived`, "Archived records are read-only.");
}

// ------------------------------------------------------------------------------------------------ lists

const listQuery = z.strictObject({ ...kpiListQuery.shape, cursor: cursorSchema, limit: limitSchema });

/**
 * A page of one kpi table for a transformation, newest change first (`updatedAt` desc, `id` desc), archived rows only
 * with includeArchived=true. The four tables share the columns used here (transformation_id, status, updated_at, id).
 */
export async function listPage<T>(
  db: Db,
  request: FastifyRequest,
  table: KpiTable,
  map: (row: never) => T,
): Promise<{ items: T[]; nextCursor: string | null }> {
  const { transformationId } = parse(transformationParams, request.params, "params");
  const query = parseQuery(listQuery, request.query);
  await readScope(db, request, transformationId);
  const hash = filterHash({ table, transformationId, includeArchived: query.includeArchived });
  const after = decodeCursor(query.cursor, hash, 2);
  // One query shape for the four tables: the table name is a closed union, typed as one member for Kysely.
  let q = db
    .selectFrom(table as "baseline")
    .selectAll()
    .select(sql<string>`to_char(updated_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')`.as("sort_key"))
    .where("transformation_id", "=", transformationId);
  if (!query.includeArchived) q = q.where("status", "<>", "archived");
  if (after) {
    q = q.where(sql<boolean>`(updated_at, id) < (${String(after[0])}::timestamptz, ${String(after[1])}::uuid)`);
  }
  const rows = await q
    .orderBy("updated_at", "desc")
    .orderBy("id", "desc")
    .limit(query.limit + 1)
    .execute();
  const page = paginate(rows, query.limit, (r) => [r.sort_key, r.id], hash);
  return {
    items: page.items.map(({ sort_key: _k, ...r }) => map(r as never)),
    nextCursor: page.nextCursor,
  };
}

// ------------------------------------------------------------------------------------------------ create

/**
 * Create with an optional Idempotency-Key (same user + key + request -> the original 201 for 24 hours). `authorize`
 * runs FIRST in the transaction, before any replay lookup, so a replay is authorized afresh and never outlives a
 * revoked grant.
 */
export async function idempotentCreate<T extends { id: string; version: number }>(
  db: Db,
  request: FastifyRequest,
  reply: FastifyReply,
  collectionPath: string,
  authorize: (tx: Tx) => Promise<Scope>,
  run: (tx: Tx, scope: Scope) => Promise<T>,
): Promise<FastifyReply> {
  const principal = principalOf(request);
  const rawKey = request.headers["idempotency-key"];
  const key = rawKey === undefined ? undefined : parse(idempotencyKeySchema, rawKey, "header");
  const result = await db.transaction().execute(async (tx) => {
    const scope = await authorize(tx);
    const exec = async () => ({ status: 201, body: await run(tx, scope) });
    if (key === undefined) return { ...(await exec()), replayed: false };
    return withIdempotency(
      tx,
      { userId: principal.userId!, key, requestHash: requestHash("POST", collectionPath, request.body) },
      exec,
    );
  });
  if (result.replayed) reply.header("Idempotent-Replayed", "true");
  return sendVersioned(reply, result.status, result.body, `${collectionPath}/${result.body.id}`);
}
// T09 formula versions and their Finance validation (ADR-0024 §5-§6; REQ-PB-055, REQ-PB-056, REQ-S08-007;
// T-DG3-KBE-C):
//   GET  /benefit-formulas/{id}/versions                          all versions, newest first, with validation state
//   POST /benefit-formulas/{id}/versions                          the next immutable version, made current
//                                                                 (benefit_formula.edit; If-Match = the T09 row's version)
//   GET  /benefit-formulas/{id}/versions/{versionNo}              one version with its typed variables
//   POST /benefit-formulas/{id}/versions/{versionNo}/validation   Finance validation of the benefit logic
//                                                                 (finance.validate; If-Match = the version's version)
//
// - A version is parsed and type-checked by the shared engine (`@mth/shared/calc`) BEFORE anything is written: an
//   invalid expression writes nothing. The schema check is 400; a body the schema admits but the engine refuses is 422
//   with the engine's first error (`formula.undefined_variable` 'Undefined variable: {name}', `formula.period_mismatch`
//   for monthly ARPU x annual customers, ...).
// - Versions are immutable (DB trigger benefit_formula_version_freeze); variables are append-only per version. Each
//   stores expression_sha256, the result kind/unit/currency/period, the preview result (Unknown = null, never 0) and
//   the engine version. A new version starts `unvalidated` and becomes the current one.
// - Finance validation: `validated` or `rejected` with a note, by a holder of finance.validate who did not author the
//   version (403 finance.validator_is_author; DB CHECK benefit_formula_version_validator_not_author too). Final once
//   recorded; a version never goes stale because it never changes.
// A Finance validation here is a recorded human decision inside the product; nothing here grants a real business,
// Finance or IT approval, and nothing touches the engineering gates DG0-DG7.
import { diffFields, sql, type BenefitFormulaVersionRow, type DbOrTx, type Tx } from "@mth/db";
import { PROBLEM_TYPES } from "@mth/shared";
import { benefitFormulaVersionCreate, financeValidationRequest } from "@mth/shared/schemas";
import type { FastifyInstance, FastifyRequest } from "fastify";
import { z } from "zod";
import { denialOf, principalOf, requireTransformationRead } from "../access/index.ts";
import { record } from "../audit/index.ts";
import {
  HttpProblem,
  parse,
  parseBody,
  problems,
  requireIfMatch,
  sendVersioned,
  type ModuleDeps,
} from "../platform/index.ts";
import { openWrite, type WriteContext } from "../transformations/index.ts";
import {
  archivedFormula,
  checkWithEngine,
  FORMULA_EDIT,
  FORMULA_ITEM,
  FORMULA_VERSION_AUDIT_FIELDS,
  formulaTransformation,
  insertFormulaVersion,
  JSON_BODY,
  lockFormula,
  presentVersions,
  setCurrentVersion,
} from "./benefit-formulas.ts";

export const VERSIONS = `${FORMULA_ITEM}/versions`;
export const VERSION_ITEM = `${VERSIONS}/:versionNo`;

// ------------------------------------------------------------------------------------------------ params and reads

const versionParams = z.strictObject({
  benefitFormulaId: z.uuid(),
  versionNo: z
    .string()
    .regex(/^[1-9][0-9]{0,8}$/, "validation.version_no")
    .transform((v) => Number.parseInt(v, 10)),
});

export function parseVersionParams(params: unknown): { formulaId: string; versionNo: number } {
  const p = parse(versionParams, params, "params");
  return { formulaId: p.benefitFormulaId, versionNo: p.versionNo };
}

/** One version of a formula the caller can read (404 otherwise). */
export async function readVersion(
  db: DbOrTx,
  request: FastifyRequest,
  formulaId: string,
  versionNo: number,
): Promise<BenefitFormulaVersionRow> {
  const transformationId = await formulaTransformation(db, formulaId);
  await requireTransformationRead(db, principalOf(request), transformationId);
  const row = await db
    .selectFrom("benefit_formula_version")
    .selectAll()
    .where("formula_id", "=", formulaId)
    .where("version_no", "=", versionNo)
    .executeTakeFirst();
  if (!row) throw problems.notFound();
  return row;
}

/** Locks one version row (FOR UPDATE: the validation; FOR SHARE: a calculation recorded against it). */
export async function lockVersion(
  tx: Tx,
  transformationId: string,
  formulaId: string,
  versionNo: number,
  mode: "update" | "share",
): Promise<BenefitFormulaVersionRow> {
  let q = tx
    .selectFrom("benefit_formula_version")
    .selectAll()
    .where("formula_id", "=", formulaId)
    .where("version_no", "=", versionNo)
    .where("transformation_id", "=", transformationId);
  q = mode === "update" ? q.forUpdate() : q.forShare();
  const row = await q.executeTakeFirst();
  if (!row) throw problems.notFound();
  return row;
}

// ------------------------------------------------------------------------------------------------ create version

async function createVersion(tx: Tx, request: FastifyRequest, formulaId: string) {
  const transformationId = await formulaTransformation(tx, formulaId);
  const ctx = await openWrite(tx, request, transformationId, [{ permission: FORMULA_EDIT }], null, {
    atCommit: true,
  });
  const expected = requireIfMatch(request);
  const body = parseBody(benefitFormulaVersionCreate, request.body);
  // Parse and type-check before anything is written: an invalid expression writes nothing (422).
  const checked = checkWithEngine(body);
  const current = await lockFormula(tx, transformationId, formulaId, "update");
  if (current.version !== expected) throw problems.versionConflict(current.version);
  if (current.status === "archived") throw archivedFormula();
  const versionNo = (current.current_version_no ?? 0) + 1;
  const version = await insertFormulaVersion(tx, ctx, current, versionNo, body, checked.checked);
  await setCurrentVersion(tx, ctx, current, versionNo, false);
  return version;
}

// ------------------------------------------------------------------------------------------------ Finance validation

const forbiddenAuthor = (ctx: WriteContext) =>
  new HttpProblem({
    status: 403,
    type: PROBLEM_TYPES.forbidden,
    code: "finance.validator_is_author",
    title: "Forbidden",
    detail: "Finance validation is done by someone other than the record's author (separation of duties).",
  }).withDenial(denialOf("finance.validate", ctx.target));

async function validateVersion(tx: Tx, request: FastifyRequest, formulaId: string, versionNo: number) {
  const transformationId = await formulaTransformation(tx, formulaId);
  const ctx = await openWrite(tx, request, transformationId, [{ permission: "finance.validate" }], null, {
    atCommit: true,
  });
  const expected = requireIfMatch(request);
  const decision = parseBody(financeValidationRequest, request.body);
  const formula = await lockFormula(tx, transformationId, formulaId, "share");
  const current = await lockVersion(tx, transformationId, formulaId, versionNo, "update");
  // Separation of duties (ADR-0024 §5; DB CHECK benefit_formula_version_validator_not_author): never the author.
  if (current.created_by === ctx.userId) throw forbiddenAuthor(ctx);
  if (current.version !== expected) throw problems.versionConflict(current.version);
  if (formula.status === "archived") throw archivedFormula();
  if (current.validation_status !== "unvalidated")
    throw problems.businessRule(
      "benefit_formula_version.validation_final",
      "The Finance validation of this formula version is final; create a new version to change the benefit logic.",
    );
  const updated = await tx
    .updateTable("benefit_formula_version")
    .set({
      validation_status: decision.result,
      validated_by: ctx.userId,
      validated_at: sql<Date>`now()`,
      validation_note: decision.note,
      version: sql<number>`version + 1`,
      updated_at: sql<Date>`now()`,
      updated_by: ctx.userId,
    })
    .where("id", "=", current.id)
    .where("version", "=", current.version)
    .returningAll()
    .executeTakeFirstOrThrow();
  await record(tx, ctx.audit, {
    action: decision.result === "validated" ? "benefit_formula_version.validate" : "benefit_formula_version.reject",
    recordType: "benefit_formula_version",
    recordId: current.id,
    organizationId: ctx.organizationId,
    transformationId,
    priorVersion: current.version,
    newVersion: updated.version,
    reason: decision.note,
    changes: diffFields(current, updated, [...FORMULA_VERSION_AUDIT_FIELDS]),
  });
  return updated;
}

// ------------------------------------------------------------------------------------------------ routes

export function registerFormulaVersionRoutes(app: FastifyInstance, { db }: ModuleDeps): readonly string[] {
  const read = { access: { permission: "transformation.read" as const } };

  app.get(VERSIONS, { config: read }, async (request) => {
    const formulaId = parse(z.strictObject({ benefitFormulaId: z.uuid() }), request.params, "params").benefitFormulaId;
    const transformationId = await formulaTransformation(db, formulaId);
    await requireTransformationRead(db, principalOf(request), transformationId);
    const rows = await db
      .selectFrom("benefit_formula_version")
      .selectAll()
      .where("formula_id", "=", formulaId)
      .orderBy("version_no", "desc")
      .execute();
    return { items: await presentVersions(db, rows) };
  });

  app.post(
    VERSIONS,
    { config: { access: { permission: FORMULA_EDIT }, consumes: JSON_BODY } },
    async (request, reply) => {
      const formulaId = parse(
        z.strictObject({ benefitFormulaId: z.uuid() }),
        request.params,
        "params",
      ).benefitFormulaId;
      const row = await db.transaction().execute((tx) => createVersion(tx, request, formulaId));
      const [body] = await presentVersions(db, [row]);
      return sendVersioned(reply, 201, body!, `/api/v1/benefit-formulas/${formulaId}/versions/${row.version_no}`);
    },
  );

  app.get(VERSION_ITEM, { config: read }, async (request, reply) => {
    const { formulaId, versionNo } = parseVersionParams(request.params);
    const row = await readVersion(db, request, formulaId, versionNo);
    const [body] = await presentVersions(db, [row]);
    return sendVersioned(reply, 200, body!);
  });

  app.post(
    `${VERSION_ITEM}/validation`,
    { config: { access: { permission: "finance.validate" }, consumes: JSON_BODY } },
    async (request, reply) => {
      const { formulaId, versionNo } = parseVersionParams(request.params);
      const row = await db.transaction().execute((tx) => validateVersion(tx, request, formulaId, versionNo));
      const [body] = await presentVersions(db, [row]);
      return sendVersioned(reply, 200, body!);
    },
  );

  return [`GET ${VERSIONS}`, `POST ${VERSIONS}`, `GET ${VERSION_ITEM}`, `POST ${VERSION_ITEM}/validation`];
}

