  createdBy: uuid,
  updatedAt: timestamp,
});
export type TargetTrajectory = z.infer<typeof targetTrajectory>;
export const targetTrajectoryPage = page(targetTrajectory);

export const targetTrajectoryListQuery = z.strictObject({
  scopeKind: kpiScopeKind.optional(),
